<script lang="ts">import {rows,text,numeric,priced,stamp,number,type Row,type Query}from'../lib/api';import{tr}from'../lib/i18n';import Quota from './Quota.svelte';import Metrics from './Metrics.svelte';import Chart from './Chart.svelte';import Filters from './Filters.svelte';import Model from './Model.svelte';import Details from './Details.svelte';export let data:Row={};export let query:Query;export let onchange:(q:Query)=>void;export let onerror:(e:any)=>void;let selected='';let values:Row={};$: summary=data.summary??{};$: input=number(summary.input_tokens);$: read=number(summary.cached_input_tokens);$: write=number(summary.cache_write_input_tokens);$: output=number(summary.output_tokens);$: valid=input!==null&&read!==null&&write!==null&&output!==null&&read+write<=input;$: values={regular_input:valid?input!-read!-write!:null,cached_input_tokens:read,cache_write_input_tokens:write,output_tokens:output};$: parts=[['regular_input','普通输入','var(--input)'],['cached_input_tokens','缓存读取','var(--cache)'],['cache_write_input_tokens','缓存写入','var(--write)'],['output_tokens','输出','var(--output)']].filter(p=>p[0]!=='cache_write_input_tokens'||(write??0)>0);$: total=valid?input!+output!:0;</script>
<Filters {query} models={data.models??[]} {onchange}/><div class="overview-top"><Quota quota={data.quota??{}}/><section class="surface token-card"><h3>{tr('Token 组成')}</h3><div class="token-bar">{#each parts as [key,label,color]}<span style:background={color} style:flex-grow={valid?(number(values[key])??0):0} title={`${tr(label)} ${numeric(values[key])}`}></span>{/each}</div><div class="token-legend">{#each parts as [key,label,color]}<span><i style:background={color}></i>{tr(label)} {valid&&total>0?((number(values[key])??0)/total*100).toFixed(1)+'%':'—'}</span>{/each}</div></section></div><Metrics {summary} comparison={data.comparison??{}}/><Chart data={data.chart??[]}/><section class="surface recent"><h3>{tr('最近请求')}</h3>{#each rows(data.recent).filter(r=>!['automatic_approval_review','context_compaction'].includes(r.record_kind)).slice(0,3) as r}<button class="recent-row quiet" onclick={()=>selected=String(r.id)}><div><strong>{text(r.prompt_preview??r.session_title)}</strong><small>{stamp(r.timestamp)} · {text(r.session_title)}</small></div><Model record={r}/><span>{numeric(r.total_tokens)} Token<br/><small>{priced(r)}</small></span></button>{/each}{#if !rows(data.recent).length}<div class="empty small">{tr('暂无数据')}</div>{/if}</section>{#if selected}<div class="detail-overlay"><button class="overlay-close" onclick={()=>selected=''}>{tr('关闭')}</button><Details id={selected} {onerror}/></div>{/if}
